package java.util;
import java.util.function.Supplier; public final class Objects { private Objects(){} public static boolean equals(Object a,Object b){return a==b||(a!=null&&a.equals(b));} public static int hashCode(Object a){return a==null?0:a.hashCode();} public static int hash(Object... a){return Arrays.hashCode(a);} public static String toString(Object a){return String.valueOf(a);} public static String toString(Object a,String d){return a==null?d:a.toString();} public static <T> T requireNonNull(T a){if(a==null)throw new NullPointerException();return a;} public static <T> T requireNonNull(T a,String m){if(a==null)throw new NullPointerException(m);return a;} public static <T> T requireNonNull(T a,Supplier<String> m){if(a==null)throw new NullPointerException(m.get());return a;} public static <T> T requireNonNullElse(T a,T b){return a!=null?a:requireNonNull(b);} public static boolean isNull(Object a){return a==null;} public static boolean nonNull(Object a){return a!=null;} public static <T> int compare(T a,T b,Comparator<? super T> c){return a==b?0:c.compare(a,b);} }
